edits.newText:
const heading = document.createElement('h1');
heading.textContent = project.name;
if (project.archived) { const notice = document.createElement('p'); notice.textContent = 'Archived project'; app.append(notice); }
else {
  const renameForm = document.createElement('form');
  const renameLabel = document.createElement('label');
  renameLabel.textContent = 'New project name';
  const renameInput = document.createElement('input');
  renameInput.type = 'text';
  renameInput.setAttribute('aria-label', 'New project name');
  renameLabel.append(renameInput);
  const renameButton = document.createElement('button');
  renameButton.type = 'submit';
  renameButton.textContent = 'Rename project';
  renameForm.append(renameLabel, renameButton);
  renameForm.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = renameInput.value.trim();
    if (!name) { showError('Project name is required'); renameInput.focus(); return; }
    const result = await fetch(`/api/projects/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
    if (!result.ok) { const error = await result.json(); showError(error.error || 'Could not rename project'); return; }
    app.querySelector('[role="alert"]')?.remove();
    render();
  });
  app.append(renameForm);
}
const form = document.createElement('form');

